window.RP_SESSION={"id":"S-5447466d8289","messages":[{"id":"RP-II-0082921","time":"2026-04-14T08:53:00+09:00","room":"RP II","name":"우슬라","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"고 좋은아침이구만 기래...\"\n\n길드 마당을 서성이는 우슬라.\n아침 이슬이 바지 밑단을 적시는 상쾌한 감각이 다리를 타고 올라온다.\n\n어제 하루종일 훈련장에서 운동한 터라, 꽤나 지쳐 보인다...","characters":["P-d077092ffb19"]},{"id":"RP-II-0082922","time":"2026-04-14T09:50:00+09:00","room":"RP II","name":"라쿠나","profile":"테론 이스트가드","identity":"reviewed","type":"dialogue","body":"\"고 좋은아침... 이구만.. 기래~\"\n\n 기지개를 쭈욱ㅡ 키며 우슬라 옆에 다가온 라쿠나","characters":["P-c2ae9261373e"]},{"id":"RP-II-0082923","time":"2026-04-14T09:52:00+09:00","room":"RP II","name":"라쿠나","profile":"테론 이스트가드","identity":"reviewed","type":"dialogue","body":"주머니를 뒤지더니 무언갈 건네주려 한다","characters":["P-c2ae9261373e"]},{"id":"RP-II-0082924","time":"2026-04-14T09:53:00+09:00","room":"RP II","name":"우슬라","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"거 님자는 뭔데 내 말을 따라는기야?\"","characters":["P-d077092ffb19"]},{"id":"RP-II-0082925","time":"2026-04-14T09:54:00+09:00","room":"RP II","name":"라쿠나","profile":"테론 이스트가드","identity":"reviewed","type":"dialogue","body":"'뒤적뒤적-'\n\n 그의 주머니에서 나온 건..\n\n지렁이 한 마리..\n\n\"우슬라.. 지렁이! 선물!\"","characters":["P-c2ae9261373e"]},{"id":"RP-II-0082926","time":"2026-04-14T09:55:00+09:00","room":"RP II","name":"우슬라","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"...이거이 뭐이가?\"\n\n그가 내민 지렁이를 받아들고는, 잠시 고민하더니...\n\n\"낚시 미끼로 쓰믄 딱이겠구만기래.\"","characters":["P-d077092ffb19"]},{"id":"RP-II-0082927","time":"2026-04-14T09:55:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"하품하고서는 마리우스 역시도 길드 마당을 지나쳐 가기 시작합니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-II-0082928","time":"2026-04-14T09:55:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"훈련해야지······.","characters":["P-b6d81d634c6e"]},{"id":"RP-II-0082929","time":"2026-04-14T09:56:00+09:00","room":"RP II","name":"라쿠나","profile":"테론 이스트가드","identity":"reviewed","type":"dialogue","body":"\"낚시 미끼로 쓰믄.. 딱이겠구만기래?!\"\n\n 그게 아니라는 듯이 손을 막 휘젓는다","characters":["P-c2ae9261373e"]},{"id":"RP-II-0082930","time":"2026-04-14T09:57:00+09:00","room":"RP II","name":"라쿠나","profile":"테론 이스트가드","identity":"reviewed","type":"dialogue","body":"\"주방, 음식.. 수프? 이게 어찌 된 일이야?\"\n\n 먹을 거라고 말하는 듯하다","characters":["P-c2ae9261373e"]},{"id":"RP-II-0082931","time":"2026-04-14T10:00:00+09:00","room":"RP II","name":"우슬라","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"이그 머그라고? 티껍다야.\"","characters":["P-d077092ffb19"]},{"id":"RP-II-0082932","time":"2026-04-14T10:02:00+09:00","room":"RP II","name":"우슬라","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"내이 수태 시장헌것도 아니구, 거 지렁이를 와 먹간?\"","characters":["P-d077092ffb19"]},{"id":"RP-II-0082933","time":"2026-04-14T10:02:00+09:00","room":"RP II","name":"우슬라","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"낚싯대를 꺼냅니다.","characters":["P-d077092ffb19"]},{"id":"RP-II-0082934","time":"2026-04-14T10:07:00+09:00","room":"RP II","name":"우슬라","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"거 님자도 요상한 거 줏어자시지말구 좀 말짱한 거 자시라. 알간?\"","characters":["P-d077092ffb19"]},{"id":"RP-II-0082935","time":"2026-04-14T11:08:00+09:00","room":"RP II","name":"라쿠나","profile":"테론 이스트가드","identity":"reviewed","type":"dialogue","body":"\"거 님자도.. 요상한 거... 줏.. 줏어자시지말구? 좀 말짱한 거 자시라.. 알간?\"\n\n 말투가 특이해서 따라 하기가 좀 어려운가 봅니다.","characters":["P-c2ae9261373e"]},{"id":"RP-II-0082936","time":"2026-04-14T11:15:00+09:00","room":"RP II","name":"라쿠나","profile":"테론 이스트가드","identity":"reviewed","type":"dialogue","body":"\"에이... 뭐이가-\"\n\n 폴짝거리며 어딘가로 사라집니다","characters":["P-c2ae9261373e"]},{"id":"RP-II-0082937","time":"2026-04-14T11:36:00+09:00","room":"RP II","name":"라쿠나","profile":"테론 이스트가드","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-c2ae9261373e"]}]};
